{
  "requirement_id": "REQ-007",
  "cases": [
    {
      "id": "TC-1",
      "title": "Project member can read task detail successfully",
      "surface": "api",
      "steps": [
        "POST /api/projects with header X-User: alice to create a project",
        "POST /api/projects/{pid}/tasks with header X-User: alice to create a task",
        "GET /api/tasks/{tid} with header X-User: alice"
      ],
      "expected": "專案、任務列表、任務詳情（GET /api/tasks/{tid}）僅限該專案成員讀取"
    },
    {
      "id": "TC-2",
      "title": "Non-member receives 403 when trying to read task detail",
      "surface": "api",
      "steps": [
        "POST /api/projects with header X-User: alice to create a project",
        "POST /api/projects/{pid}/tasks with header X-User: alice to create a task",
        "GET /api/tasks/{tid} with header X-User: bob"
      ],
      "expected": "非專案成員存取時回傳 403 錯誤"
    },
    {
      "id": "TC-3",
      "title": "Non-member receives 403 when trying to read project tasks list",
      "surface": "api",
      "steps": [
        "POST /api/projects with header X-User: alice to create a project",
        "GET /api/projects/{pid}/tasks with header X-User: bob"
      ],
      "expected": "非專案成員存取時回傳 403 錯誤"
    },
    {
      "id": "TC-4",
      "title": "Requesting a non-existent task returns 404 error",
      "surface": "api",
      "steps": [
        "GET /api/tasks/999999 with header X-User: alice"
      ],
      "expected": "請求的資源不存在時回傳 404 錯誤"
    }
  ]
}

